  3→export function checkPermission(
  4→  role: string,
  5→  resource: string,
  6→  action: string
  7→): boolean {
  8→  const db = getDb();
  9→
 10→  // 먼저 와일드카드 '*' 체크
 11→  const wildcard = db
 12→    .prepare(
 13→      "SELECT allowed FROM permissions WHERE role = ? AND resource = '*' AND action = ? LIMIT 1"
 14→    )
 15→    .get(role, action) as { allowed: number } | undefined;
 16→
 17→  if (wildcard) return wildcard.allowed === 1;
 18→
 19→  // 정확한 resource 체크
 20→  const exact = db
 21→    .prepare(
 22→      "SELECT allowed FROM permissions WHERE role = ? AND resource = ? AND action = ? LIMIT 1"
 23→    )
 24→    .get(role, resource, action) as { allowed: number } | undefined;
 25→
 26→  if (exact) return exact.allowed === 1;
 27→
 28→  // 권한 레코드가 없으면 거부
 29→  return false;
 30→}
 31→
 32→export function getPermissionsForRole(role: string): {
 33→  resource: string;
 34→  action: string;
 35→  allowed: boolean;
 36→}[] {
 37→  const db = getDb();
 38→  const rows = db
 39→    .prepare("SELECT resource, action, allowed FROM permissions WHERE role = ?")
 40→    .all(role) as { resource: string; action: string; allowed: number }[];
 41→  return rows.map((r) => ({
 42→    resource: r.resource,
 43→    action: r.action,
 44→    allowed: r.allowed === 1,
 45→  }));
 46→}
 47→
 48→export function updatePermissions(
 49→  role: string,
 50→  changes: { resource: string; action: string; allowed: boolean }[]
 51→): void {
 52→  const db = getDb();
 53→  const upsert = db.prepare(`
 54→    INSERT INTO permissions (role, resource, action, allowed)
 55→    VALUES (?, ?, ?, ?)
 56→    ON CONFLICT(role, resource, action)
 57→    DO UPDATE SET allowed = excluded.allowed, updated_at = CURRENT_TIMESTAMP
 58→  `);
 59→  const tx = db.transaction(() => {
 60→    for (const c of changes) {
 61→      upsert.run(role, c.resource, c.action, c.allowed ? 1 : 0);
 62→    }
 63→  });
 64→  tx();
 65→}
 66→
 67→export function getAllRoles(): string[] {
 68→  const db = getDb();
 69→  const rows = db
 70→    .prepare("SELECT DISTINCT role FROM permissions ORDER BY role")
 71→    .all() as { role: string }[];
 72→  return rows.map((r) => r.role);
 73→}
 74→
 75→export function createRole(role: string): void {
 76→  const db = getDb();
 77→  const RESOURCES = [
 78→    "dashboard.summary", "dashboard.allocation", "dashboard.progress",
 79→    "candidates", "procedures", "actions",
 80→    "admin.data-sheet", "admin.workflow",
 81→    "system.permissions", "system.users",
 82→    "etc",
 83→  ];
 84→  const ACTIONS = ["view", "edit", "delete", "export", "import"];
 85→  const insert = db.prepare(
 86→    "INSERT OR IGNORE INTO permissions (role, resource, action, allowed) VALUES (?, ?, ?, 0)"
 87→  );
 88→  const tx = db.transaction(() => {
 89→    for (const resource of RESOURCES) {
 90→      for (const action of ACTIONS) {
 91→        insert.run(role, resource, action);
 92→      }
 93→    }
 94→  });
 95→  tx();
 96→}
 97→
 98→export function deleteRole(role: string): { success: boolean; error?: string } {
 99→  const db = getDb();
100→  const userCount = db
101→    .prepare("SELECT COUNT(*) as count FROM users WHERE role = ?")
102→    .get(role) as { count: number };
103→  if (userCount.count > 0) {
104→    return { success: false, error: `${userCount.count}명의 사용자가 이 역할을 사용 중입니다.` };
105→  }
106→  db.prepare("DELETE FROM permissions WHERE role = ?").run(role);
107→  return { success: true };
108→}
109→
110→export function getViewableResources(role: string): string[] {
111→  const db = getDb();
112→
113→  // 와일드카드 체크
114→  const wildcard = db
115→    .prepare("SELECT allowed FROM permissions WHERE role = ? AND resource = '*' AND action = 'view'")
116→    .get(role) as { allowed: number } | undefined;
117→
118→  if (wildcard?.allowed === 1) {
119→    return [
120→      "dashboard.summary", "dashboard.allocation", "dashboard.progress",
121→      "candidates", "procedures", "actions",
122→      "admin.data-sheet", "admin.workflow",
123→      "system.permissions", "system.users",
124→    ];
125→  }
126→
127→  const rows = db
128→    .prepare("SELECT resource FROM permissions WHERE role = ? AND action = 'view' AND allowed = 1")
129→    .all(role) as { resource: string }[];
130→  return rows.map((r) => r.resource);
131→}
