"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import type { AuthUser } from "@/lib/types";

type MenuSection = {
  label?: string;
  items: { icon: string; label: string; href: string; resource: string }[];
};

const ADMIN_MENU: MenuSection[] = [
  {
    items: [
      { icon: "\u{1F4CA}", label: "\uD604\uD669 \uC694\uC57D", href: "/summary", resource: "dashboard.summary" },
      { icon: "\u{1F4CB}", label: "TO \uBC30\uBD84\uD45C", href: "/allocation", resource: "dashboard.allocation" },
      { icon: "\u{1F504}", label: "\uCC44\uC6A9 \uC9C4\uD589\uD604\uD669", href: "/progress", resource: "dashboard.progress" },
      { icon: "\u{1F464}", label: "\uD6C4\uBCF4\uC790 \uAD00\uB9AC", href: "/candidates", resource: "candidates" },
    ],
  },
  {
    label: "\uAD00\uB9AC",
    items: [
      { icon: "\u{2699}\uFE0F", label: "\uB370\uC774\uD130 \uAD00\uB9AC", href: "/data-sheet", resource: "admin.data-sheet" },
      { icon: "\u{1F4D0}", label: "\uC6CC\uD06C\uD50C\uB85C\uC6B0", href: "/workflow", resource: "admin.workflow" },
    ],
  },
  {
    label: "\uC2DC\uC2A4\uD15C",
    items: [
      { icon: "\u{1F510}", label: "\uAD8C\uD55C \uAD00\uB9AC", href: "/permissions", resource: "system.permissions" },
      { icon: "\u{1F465}", label: "\uC0AC\uC6A9\uC790 \uAD00\uB9AC", href: "/users", resource: "system.users" },
    ],
  },
];

const DEAN_MENU: MenuSection[] = [
  {
    items: [
      { icon: "\u{1F4CA}", label: "\uD559\uACFC \uD604\uD669", href: "/summary", resource: "dashboard.summary" },
      { icon: "\u{1F504}", label: "\uCC44\uC6A9 \uC9C4\uD589\uD604\uD669", href: "/progress", resource: "dashboard.progress" },
      { icon: "\u{1F464}", label: "\uD6C4\uBCF4\uC790 \uAD00\uB9AC", href: "/candidates", resource: "candidates" },
    ],
  },
];

function getMenuForRole(role: string): MenuSection[] {
  if (role === "DEAN") return DEAN_MENU;
  return ADMIN_MENU; // ADMIN and VIP get the same menu
}

function filterMenuByResources(
  menu: MenuSection[],
  viewableResources: string[]
): MenuSection[] {
  return menu
    .map((section) => ({
      ...section,
      items: section.items.filter((item) =>
        viewableResources.includes(item.resource)
      ),
    }))
    .filter((section) => section.items.length > 0);
}

function isActive(pathname: string, href: string): boolean {
  if (href === "/") return pathname === "/";
  return pathname === href || pathname.startsWith(href + "/");
}

export default function Sidebar({
  user,
  viewableResources,
}: {
  user: AuthUser;
  viewableResources: string[];
}) {
  const pathname = usePathname();
  const baseMenu = getMenuForRole(user.role);
  const menu = filterMenuByResources(baseMenu, viewableResources);

  return (
    <aside
      style={{
        width: 220,
        background: "var(--sidebar-bg)",
        padding: "20px 0",
        flexShrink: 0,
        position: "fixed",
        top: 0,
        left: 0,
        bottom: 0,
        display: "flex",
        flexDirection: "column",
        zIndex: 50,
        overflowY: "auto",
      }}
    >
      {/* Logo + Title */}
      <div style={{ padding: "0 16px 20px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div
            style={{
              width: 36,
              height: 36,
              borderRadius: "50%",
              background: "rgba(255,255,255,0.85)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
            }}
          >
            <Image
              src="/logo_SKKU_colored.png"
              alt="SKKU"
              width={26}
              height={26}
              style={{ objectFit: "contain" }}
              unoptimized
            />
          </div>
          <div>
            <div
              style={{
                fontWeight: 700,
                fontSize: 14,
                color: "var(--sidebar-text-active)",
                lineHeight: 1.2,
              }}
            >
              교원채용
            </div>
            <div
              style={{
                fontSize: 10,
                color: "var(--sidebar-text)",
                marginTop: 2,
              }}
            >
              성균관대학교
            </div>
          </div>
        </div>
      </div>

      {/* Menu */}
      <nav style={{ flex: 1, padding: "0 8px" }}>
        {menu.map((section, sIdx) => (
          <div key={sIdx}>
            {section.label && (
              <div
                style={{
                  fontSize: 10,
                  fontWeight: 600,
                  color: "var(--sidebar-section)",
                  textTransform: "uppercase",
                  padding: "16px 12px 6px",
                  letterSpacing: "0.05em",
                }}
              >
                {section.label}
              </div>
            )}
            {section.items.map((item) => {
              const active = isActive(pathname, item.href);
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                    padding: "9px 12px",
                    marginBottom: 2,
                    borderRadius: 6,
                    fontSize: 13,
                    fontWeight: active ? 600 : 400,
                    color: active
                      ? "var(--sidebar-text-active)"
                      : "var(--sidebar-text)",
                    background: active ? "var(--sidebar-hover)" : "transparent",
                    textDecoration: "none",
                    transition: "background 0.15s, color 0.15s",
                  }}
                >
                  <span style={{ fontSize: 14, lineHeight: 1 }}>
                    {item.icon}
                  </span>
                  {item.label}
                </Link>
              );
            })}
          </div>
        ))}
      </nav>

      {/* Dean department info */}
      {user.role === "DEAN" && user.departmentCode && (
        <div
          style={{
            padding: "12px 16px",
            borderTop: "1px solid rgba(255,255,255,0.08)",
          }}
        >
          <div
            style={{
              fontSize: 10,
              color: "var(--sidebar-section)",
              marginBottom: 4,
            }}
          >
            소속 학과
          </div>
          <div
            style={{
              fontSize: 12,
              color: "var(--sidebar-text)",
            }}
          >
            {user.departmentCode}
          </div>
        </div>
      )}

      {/* User info at bottom */}
      <div
        style={{
          padding: "16px 16px 4px",
          borderTop: "1px solid rgba(255,255,255,0.08)",
        }}
      >
        <div
          style={{
            fontSize: 12,
            fontWeight: 600,
            color: "var(--sidebar-text-active)",
          }}
        >
          {user.username}
        </div>
        <div
          style={{
            fontSize: 10,
            color: "var(--sidebar-text)",
            marginTop: 2,
          }}
        >
          {user.role}
        </div>
      </div>
    </aside>
  );
}

import type { Metadata } from "next";
import "./globals.css";
