          <>
            <Sidebar user={user} viewableResources={viewableResources} />
            <main
              style={{
                marginLeft: 220,
                padding: "24px 28px",
                background: "var(--page-bg)",
                minHeight: "100vh",
              }}
            >
              {children}
            </main>
